def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    events_by_col = [[] for _ in range(w)]

    # A single-cell gap within a horizontal bar is a colored crossing.
    for r in range(h):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r][c - 1] != 0
                    and grid[r][c - 1] == grid[r][c + 1]):
                events_by_col[c].append((r, grid[r][c - 1]))

    for c, events in enumerate(events_by_col):
        if not events:
            continue
        events.sort()

        # The first crossing color extends upward.
        first_r, first_color = events[0]
        for r in range(first_r + 1):
            out[r][c] = first_color

        # Each subsequent crossing sets the color through its row.
        for (r1, _), (r2, color) in zip(events, events[1:]):
            for r in range(r1 + 1, r2 + 1):
                out[r][c] = color

        # The vertical marker below the horizontal bars extends upward from
        # the final crossing, filling the remaining cells in that column.
        last_r = events[-1][0]
        marker = next((grid[r][c] for r in range(last_r + 1, h)
                       if grid[r][c] != 0), None)
        if marker is not None:
            for r in range(last_r + 1, h):
                out[r][c] = marker

    return out
